CREATE TABLE market_prices(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`listing_id` bigint  NULL COMMENT 'Reference to marketplace listing',`booking_id` bigint  NULL COMMENT 'Reference to advance booking',`transaction_id` bigint  NULL COMMENT 'Reference to livestock transaction',`item_type` varchar(50)  NOT NULL COMMENT 'crop, livestock',`item_name` varchar(255)  NOT NULL COMMENT 'Crop type or livestock species',`variety` varchar(255)  NULL COMMENT 'Crop variety or livestock breed',`price_per_unit` DECIMAL(10,2)  NOT NULL COMMENT 'Price per kg for crops, per animal for livestock',`quantity` DECIMAL(10,2)  NOT NULL COMMENT 'Quantity in kg or number of animals',`total_value` DECIMAL(12,2)  NOT NULL COMMENT 'Total transaction value in INR',`quality_grade` varchar(10)  NULL COMMENT 'A, B, C grade for crops',`quality_premium_percent` DECIMAL(5,2)  NULL COMMENT 'Premium percentage for quality',`state` varchar(100)  NOT NULL,`district` varchar(100)  NOT NULL,`transaction_date` timestamp  NOT NULL DEFAULT CURRENT_TIMESTAMP,`season` varchar(50)  NULL COMMENT 'Kharif, Rabi, Zaid',`source` varchar(50)  NOT NULL COMMENT 'marketplace, booking, livestock_transaction')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;